(416404, 37414, 11034, '<td valign="top">A very nice sky. Good color.</td>', 'A very nice sky. Good color.', '2003-09-12 01:40:40.000000', NULL, 1),
(416405, 37388, 7969, '<td valign="top">Shame they had to build those buildings in the midst of such a pristine location. Would like to see it cropped over the buildings, see the mountains and sky, the light on the mnt. is the fabulous part of your shot IMO.  Good clouds too.</td>', 'Shame they had to build those buildings in the midst of such a pristine location. Would like to see it cropped over the buildings, see the mountains and sky, the light on the mnt. is the fabulous part of your shot IMO.  Good clouds too.', '2003-09-12 01:41:01.000000', NULL, 1),
(416407, 37448, 7969, '<td valign="top">The lighting and tones in this image IMO are superb. very nice job, my choice for the blue ribbon.</td>', 'The lighting and tones in this image IMO are superb. very nice job, my choice for the blue ribbon.', '2003-09-12 01:42:05.000000', NULL, 1),
(416410, 37406, 10263, '<td valign="top">heh this one made me laugh out loud. Must have had a nice wind. The pole seems a little out of focus to me and that is distracting.</td>', 'heh this one made me laugh out loud. Must have had a nice wind. The pole seems a little out of focus to me and that is distracting.', '2003-09-12 01:45:00.000000', NULL, 1),
