(416833, 37448, 7263, '<td valign="top">finaly  great images comming up. Fantastic lighting, volumetrics and well chosen background, a 9! Would be 10 but it''s not quite central. A little cropping from the right would have done the trick.</td>', 'finaly  great images comming up. Fantastic lighting, volumetrics and well chosen background, a 9! Would be 10 but it''s not quite central. A little cropping from the right would have done the trick.', '2003-09-12 12:31:03.000000', NULL, 1),
(416841, 37344, 11155, '<td valign="top">Excellent image - also says "Freedom" to me.</td>', 'Excellent image - also says "Freedom" to me.', '2003-09-12 12:56:31.000000', NULL, 1),
(416842, 37396, 7242, '<td valign="top">Nice idea! I''m scared of the hand though.  6</td>', 'Nice idea! I''m scared of the hand though.  6', '2003-09-12 12:58:46.000000', NULL, 1),
(416844, 37323, 11155, '<td valign="top">Great capture - colors look a little weak, but that may be the intention.  Great expression on the young woman''s face.  Nice.</td>', 'Great capture - colors look a little weak, but that may be the intention.  Great expression on the young woman''s face.  Nice.', '2003-09-12 13:01:02.000000', NULL, 1),
(416847, 37384, 11155, '<td valign="top">Powerful image, pretty much says it all.  Good luck in the contest.</td>', 'Powerful image, pretty much says it all.  Good luck in the contest.', '2003-09-12 13:03:16.000000', NULL, 1),
(416849, 37339, 7242, '<td valign="top">I really like this shot. I would have liked to see just a little bit more detail in the door though. The light coming through is excellent. 9</td>', 'I really like this shot. I would have liked to see just a little bit more detail in the door though. The light coming through is excellent. 9', '2003-09-12 13:04:35.000000', NULL, 1),
(416850, 37396, 11155, '<td valign="top">Creative image.  The hand looks a bt pixelated, but I really like the idea of the shot.  Good luck!</td>', 'Creative image.  The hand looks a bt pixelated, but I really like the idea of the shot.  Good luck!', '2003-09-12 13:05:18.000000', NULL, 1),
(416851, 37411, 7242, '<td valign="top">Cute! And well executed.</td>', 'Cute! And well executed.', '2003-09-12 13:05:39.000000', NULL, 1),
(416852, 37437, 11155, '<td valign="top">Sharp image and creative composition.  Good luck.</td>', 'Sharp image and creative composition.  Good luck.', '2003-09-12 13:06:14.000000', NULL, 1),
(416853, 37411, 11155, '<td valign="top">Haha.  This is great -  I like the light hearted look at this challenge.  Great job.  Good luck.</td>', 'Haha.  This is great -  I like the light hearted look at this challenge.  Great job.  Good luck.', '2003-09-12 13:07:07.000000', NULL, 1),
(416860, 37448, 7242, '<td valign="top">This is a standout photo. The colors and lighting are superb. 10</td>', 'This is a standout photo. The colors and lighting are superb. 10', '2003-09-12 13:13:01.000000', NULL, 1),
(416863, 37377, 7242, '<td valign="top">Nice angle and use of color. Really nice. 9</td>', 'Nice angle and use of color. Really nice. 9', '2003-09-12 13:13:45.000000', NULL, 1),
(416864, 37400, 7242, '<td valign="top">I love it. Just wish the upper left corner of the flag was less blurry. 9</td>', 'I love it. Just wish the upper left corner of the flag was less blurry. 9', '2003-09-12 13:14:29.000000', NULL, 1),
(416903, 37443, 10680, '<td valign="top">awesome job on the color! great picture</td>', 'awesome job on the color! great picture', '2003-09-12 14:04:43.000000', NULL, 1),
(416905, 37400, 10680, '<td valign="top">great shot! nice composition, great detail!</td>', 'great shot! nice composition, great detail!', '2003-09-12 14:05:34.000000', NULL, 1),
(416909, 37444, 4494, '<td valign="top">Should put the lock around the front wheel and the frame.  Looks like you have the lock around just 1 spoke?  Lucky they didn''t just cut the spoke and take all of it!</td>', 'Should put the lock around the front wheel and the frame.  Looks like you have the lock around just 1 spoke?  Lucky they didn''t just cut the spoke and take all of it!', '2003-09-12 14:08:46.000000', NULL, 1),
(416911, 37441, 10680, '<td valign="top">VERYwell done, great composition, great idea. nicely done.</td>', 'VERYwell done, great composition, great idea. nicely done.', '2003-09-12 14:09:20.000000', NULL, 1),
(416921, 37401, 4494, '<td valign="top">Wow that''s sooo cool!!</td>', 'Wow that''s sooo cool!!', '2003-09-12 14:19:33.000000', NULL, 1),
(416928, 37400, 772, '<td valign="top">Excellent shot... capturing the water drop here at just the right time was excellent :)  There are only two elements of this photo that I think could use any possible improvement... I think it would be stronger if the background green was even and the dark area on the right was the same color as the rest of the background... It could be my monitor, but there also appear to be a few sharpening artifacts as well... I will have to look at this one again on my other monitor :)  Excellent shot...</td>', 'Excellent shot... capturing the water drop here at just the right time was excellent :)  There are only two elements of this photo that I think could use any possible improvement... I think it would be stronger if the background green was even and the dark area on the right was the same color as the rest of the background... It could be my monitor, but there also appear to be a few sharpening artifacts as well... I will have to look at this one again on my other monitor :)  Excellent shot...', '2003-09-12 14:22:55.000000', NULL, 1),
(416933, 37428, 4494, '<td valign="top">Nice effect, I think it works well with this shot.  Did you use "Remove Scratches", or something like that?</td>', 'Nice effect, I think it works well with this shot.  Did you use "Remove Scratches", or something like that?', '2003-09-12 14:25:26.000000', NULL, 1),
(416935, 37440, 4494, '<td valign="top">Ain''t that the truth.</td>', 'Ain''t that the truth.', '2003-09-12 14:27:34.000000', NULL, 1),
(416936, 37443, 772, '<td valign="top">This is an excellent compposition and I like the theme of the photo.  There is a price to pay for our freedom and sometimes it is a high price.  The desaturation on this particular image under the DPC rules, unfortunately, doesn''t seem to work very well.  The little bit of blue left in the sky seems slightly awkward, and there is some darker blue hanging around the edges of the tree in the upper right that look slightly odd also.  I think this image is good and will work out very nicely as a ''finished'' photo :)  Excellent work... :)</td>', 'This is an excellent compposition and I like the theme of the photo.  There is a price to pay for our freedom and sometimes it is a high price.  The desaturation on this particular image under the DPC rules, unfortunately, doesn''t seem to work very well.  The little bit of blue left in the sky seems slightly awkward, and there is some darker blue hanging around the edges of the tree in the upper right that look slightly odd also.  I think this image is good and will work out very nicely as a ''finished'' photo :)  Excellent work... :)', '2003-09-12 14:28:12.000000', NULL, 1),
(416939, 37441, 4494, '<td valign="top">Very cool.  Awesome lighting here.  The eye and flag are perfectly in focus.  Great image!</td>', 'Very cool.  Awesome lighting here.  The eye and flag are perfectly in focus.  Great image!', '2003-09-12 14:30:42.000000', NULL, 1),
(416944, 37396, 4494, '<td valign="top">What happened to the hand?  It looks plastic or something.  I think that you had to over tweak something because of an initially bad shot, and that caused the hand to look really bad.</td>', 'What happened to the hand?  It looks plastic or something.  I think that you had to over tweak something because of an initially bad shot, and that caused the hand to look really bad.', '2003-09-12 14:32:42.000000', NULL, 1),
(416948, 37384, 4494, '<td valign="top">Cool, what flag is this?  Nice to see another country''s flag.  The handcuffs add a lot of interest to the shot.</td>', 'Cool, what flag is this?  Nice to see another country''s flag.  The handcuffs add a lot of interest to the shot.', '2003-09-12 14:34:21.000000', NULL, 1),
(416949, 37406, 4494, '<td valign="top">They shouldn''t even allow McDonalds flags on the same pole. :)  Well done, this shot REALLY conveys your message perfectly!!  The colors are great.  The pic is a little tilted to the left.  8.</td>', 'They shouldn''t even allow McDonalds flags on the same pole. :)  Well done, this shot REALLY conveys your message perfectly!!  The colors are great.  The pic is a little tilted to the left.  8.', '2003-09-12 14:36:18.000000', NULL, 1),
(416956, 37377, 6597, '<td valign="top">Yes Freedom to believe is great and a good photo too 7</td>', 'Yes Freedom to believe is great and a good photo too 7', '2003-09-12 14:46:27.000000', NULL, 1),
(416958, 37358, 6597, '<td valign="top">Glad to see your flag. Not sure which country but I will look it up overall good photo<br/>          Sue  8</td>', 'Glad to see your flag. Not sure which country but I will look it up overall good photo          Sue  8', '2003-09-12 14:49:40.000000', NULL, 1),
(416959, 37422, 6597, '<td valign="top">One of our most precious freedoms.       7</td>', 'One of our most precious freedoms.       7', '2003-09-12 14:50:31.000000', NULL, 1),
(416961, 37435, 6597, '<td valign="top">A great freedom but sometimes misused 7</td>', 'A great freedom but sometimes misused 7', '2003-09-12 14:52:09.000000', NULL, 1),
(416963, 37350, 6597, '<td valign="top">excellent photo I like the composition and color 8<br/>                    Sue</td>', 'excellent photo I like the composition and color 8                    Sue', '2003-09-12 14:55:42.000000', NULL, 1),
(416982, 37441, 9043, '<td valign="top">Superb. 10</td>', 'Superb. 10', '2003-09-12 15:11:39.000000', NULL, 1),
(416988, 37400, 8624, '<td valign="top">very creative idea. I like the exposure and tonal range of the image, but I wouldn''t have gotten the idea without the caption. perhaps not shooting in so tight might provide more context.</td>', 'very creative idea. I like the exposure and tonal range of the image, but I wouldn''t have gotten the idea without the caption. perhaps not shooting in so tight might provide more context.', '2003-09-12 15:23:18.000000', NULL, 1),
(416991, 37424, 8624, '<td valign="top">excellent idea but the image would have worked pretty well on it''s own without the negative effect.</td>', 'excellent idea but the image would have worked pretty well on it''s own without the negative effect.', '2003-09-12 15:24:40.000000', NULL, 1),
(416994, 37325, 10218, '<td valign="top">I like the idea.  I would''ve cleaned up the crayons or bought new ones.  Maybe try this on a black background to make the white stand out?    A wider range of focus would''ve been nice, too, as the tips are kinda blurry.</td>', 'I like the idea.  I would''ve cleaned up the crayons or bought new ones.  Maybe try this on a black background to make the white stand out?    A wider range of focus would''ve been nice, too, as the tips are kinda blurry.', '2003-09-12 15:26:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(416998, 37423, 10218, '<td valign="top">Very cool looking.  I like the composition a lot.  Is it fully legal, I''m wondering. ;)</td>', 'Very cool looking.  I like the composition a lot.  Is it fully legal, I''m wondering. ;)', '2003-09-12 15:28:44.000000', NULL, 1),
(417004, 37372, 10218, '<td valign="top">Very nice looking composition.  I especially like the line of stars running down the left side.  Needs some balance adjustments to make the colors stand out more, I think.  As it is, the colors are kinda dull/faded looking.</td>', 'Very nice looking composition.  I especially like the line of stars running down the left side.  Needs some balance adjustments to make the colors stand out more, I think.  As it is, the colors are kinda dull/faded looking.', '2003-09-12 15:32:58.000000', NULL, 1),
(417006, 37441, 10218, '<td valign="top">Great reflection.  Maybe take it in a bit closer so the flag is more noticeable; takes up more area in the picture.</td>', 'Great reflection.  Maybe take it in a bit closer so the flag is more noticeable; takes up more area in the picture.', '2003-09-12 15:35:26.000000', NULL, 1),
(417009, 37423, 3554, '<td valign="top">Wonderful emotion, color and artistic interpretation of the challenge. I feel the freedom of expression in this shot. 10.</td>', 'Wonderful emotion, color and artistic interpretation of the challenge. I feel the freedom of expression in this shot. 10.', '2003-09-12 15:38:27.000000', NULL, 1),
(417010, 37376, 3554, '<td valign="top">Good use of B&amp;W and lighting. Fits challenge quite well.</td>', 'Good use of B&W and lighting. Fits challenge quite well.', '2003-09-12 15:39:33.000000', NULL, 1),
(417011, 37454, 7711, '<td valign="top">what a message. Very well done, this is both artistic and original, and it speaks volumes.</td>', 'what a message. Very well done, this is both artistic and original, and it speaks volumes.', '2003-09-12 15:41:39.000000', NULL, 1),
(417012, 37437, 3554, '<td valign="top">Freedom of religion is important and many today take it for granted.This shot communicates the reminder of freedom of religion well.  I like how the flag is somewhat softer than the bible, but still prominent.</td>', 'Freedom of religion is important and many today take it for granted.This shot communicates the reminder of freedom of religion well.  I like how the flag is somewhat softer than the bible, but still prominent.', '2003-09-12 15:42:20.000000', NULL, 1),
(417022, 37397, 3554, '<td valign="top">A moody, creative shot. My eye is drawn to the faces to the right, particularly the face second from the right. The subject seems to me to be raising hands more in desperation than in freedom. Perhaps reaching for freedom? Or using his freedom to reach for whatever his desire is?  8.</td>', 'A moody, creative shot. My eye is drawn to the faces to the right, particularly the face second from the right. The subject seems to me to be raising hands more in desperation than in freedom. Perhaps reaching for freedom? Or using his freedom to reach for whatever his desire is?  8.', '2003-09-12 15:53:34.000000', NULL, 1),
(417043, 37423, 10275, '<td valign="top">Beautiful creativity. Love the colour combination. This photo has very emotional feeling in it. Well done. 10</td>', 'Beautiful creativity. Love the colour combination. This photo has very emotional feeling in it. Well done. 10', '2003-09-12 16:06:59.000000', NULL, 1),
(417046, 37411, 10275, '<td valign="top">I am with you on this one. Great choice of background.  Soft feeling. Good photo. 10</td>', 'I am with you on this one. Great choice of background.  Soft feeling. Good photo. 10', '2003-09-12 16:07:48.000000', NULL, 1),
(417048, 37440, 10275, '<td valign="top">Very well thought out. Good vertical composition. Great colour combination.</td>', 'Very well thought out. Good vertical composition. Great colour combination.', '2003-09-12 16:08:31.000000', NULL, 1),
(417051, 37400, 10275, '<td valign="top">Oh, what a great emotion this portrais. Well captured moment. Good colour contrast. The drop could be a bit sharper, but the whole photo has soft feeling so it doesn''t bother me. Love the off-tilt composition. 10</td>', 'Oh, what a great emotion this portrais. Well captured moment. Good colour contrast. The drop could be a bit sharper, but the whole photo has soft feeling so it doesn''t bother me. Love the off-tilt composition. 10', '2003-09-12 16:10:31.000000', NULL, 1),
(417054, 37401, 10275, '<td valign="top">Great shot. This is one of those must takes when you see something like this. It is a bit out of focus though and on an angle (which you may have intended)... I still like it a lot.</td>', 'Great shot. This is one of those must takes when you see something like this. It is a bit out of focus though and on an angle (which you may have intended)... I still like it a lot.', '2003-09-12 16:11:51.000000', NULL, 1),
(417057, 37323, 10275, '<td valign="top">Great emotion in this shot. Love the soft look which goes well with the subject. The girl''s face says it all. Well done. 10</td>', 'Great emotion in this shot. Love the soft look which goes well with the subject. The girl''s face says it all. Well done. 10', '2003-09-12 16:12:37.000000', NULL, 1),
(417058, 37414, 10275, '<td valign="top">Great idea, good shot.</td>', 'Great idea, good shot.', '2003-09-12 16:12:56.000000', NULL, 1),
(417060, 37326, 10275, '<td valign="top">Well centred, beatiful colour, great emotion. A bit grainy, but that''s ok. Well done.</td>', 'Well centred, beatiful colour, great emotion. A bit grainy, but that''s ok. Well done.', '2003-09-12 16:13:31.000000', NULL, 1),
(417064, 37350, 10275, '<td valign="top">Great emotion from this image, I like it. Birds to me always mean freedom.  Need more focus - it''s a bit pixelated. But I still like it.</td>', 'Great emotion from this image, I like it. Birds to me always mean freedom.  Need more focus - it''s a bit pixelated. But I still like it.', '2003-09-12 16:14:48.000000', NULL, 1),
(417065, 37432, 10275, '<td valign="top">Superb clarity and sharpness. Good choice of subject. Made me smile. Well done.</td>', 'Superb clarity and sharpness. Good choice of subject. Made me smile. Well done.', '2003-09-12 16:15:28.000000', NULL, 1),
(417070, 37422, 10275, '<td valign="top">Good concept, but poor quality image. Not sharp and poor lighting.</td>', 'Good concept, but poor quality image. Not sharp and poor lighting.', '2003-09-12 16:17:12.000000', NULL, 1),
(417073, 37450, 10275, '<td valign="top">Im sorry, but this idea with the text has been done so many times that it looses the originality. It is out of focus and off-tilt.</td>', 'Im sorry, but this idea with the text has been done so many times that it looses the originality. It is out of focus and off-tilt.', '2003-09-12 16:18:48.000000', NULL, 1),
(417075, 37456, 10275, '<td valign="top">Don''t want to attack the idea which is good. But the composition here is very boring and it is also out of focus.</td>', 'Don''t want to attack the idea which is good. But the composition here is very boring and it is also out of focus.', '2003-09-12 16:19:31.000000', NULL, 1),
(417078, 37348, 10275, '<td valign="top">The border is quite bad. Totally overtakes the image.</td>', 'The border is quite bad. Totally overtakes the image.', '2003-09-12 16:20:21.000000', NULL, 1),
(417085, 37444, 10275, '<td valign="top">This is very nice shot, but I do not get it. Can you please explain it to me. Colours are great, sharp focus, love the blurred car behind the wheel.</td>', 'This is very nice shot, but I do not get it. Can you please explain it to me. Colours are great, sharp focus, love the blurred car behind the wheel.', '2003-09-12 16:21:39.000000', NULL, 1),
(417095, 37326, 10799, '<td valign="top">The color is rich and the photograph angle makes it seem like you are standing in the church. Nice work.</td>', 'The color is rich and the photograph angle makes it seem like you are standing in the church. Nice work.', '2003-09-12 16:36:59.000000', NULL, 1),
(417098, 37344, 11022, '<td valign="top">Beautifully done.  Excellent blurred flag background sets of these symbols of the USA''s passport to freedom.</td>', 'Beautifully done.  Excellent blurred flag background sets of these symbols of the USA''s passport to freedom.', '2003-09-12 16:42:24.000000', NULL, 1),
(417099, 37410, 11155, '<td valign="top">Freedom from what or whom, I''m not going to ask, but the fact these are on a pool table...  Hmm.</td>', 'Freedom from what or whom, I''m not going to ask, but the fact these are on a pool table...  Hmm.', '2003-09-12 16:42:53.000000', NULL, 1),
(417101, 37326, 11155, '<td valign="top">Nice shot - good detail and wonderful colors.</td>', 'Nice shot - good detail and wonderful colors.', '2003-09-12 16:43:50.000000', NULL, 1),
(417103, 37459, 11022, '<td valign="top">Love everything except how the background appears purple and detracts a bit.  Still and excellent representation of the theme and a nice shot.</td>', 'Love everything except how the background appears purple and detracts a bit.  Still and excellent representation of the theme and a nice shot.', '2003-09-12 16:44:16.000000', NULL, 1),
(417104, 37377, 11022, '<td valign="top">Very timely and sort of bittersweet.  Good job on this.  I like the angle and point-of-view.</td>', 'Very timely and sort of bittersweet.  Good job on this.  I like the angle and point-of-view.', '2003-09-12 16:45:25.000000', NULL, 1),
(417105, 37410, 11022, '<td valign="top">Nice one.</td>', 'Nice one.', '2003-09-12 16:46:36.000000', NULL, 1),
(417108, 37352, 11155, '<td valign="top">Image is interesting, but I''m not sure of the connection between blood and a padlock.</td>', 'Image is interesting, but I''m not sure of the connection between blood and a padlock.', '2003-09-12 16:47:49.000000', NULL, 1),
(417109, 37441, 10978, '<td valign="top">WOW that is really cool, at first i was just like okay an eye...but looking better at it yes i like it it works. I just wish there was not so much light/glare next to it. but still a 7</td>', 'WOW that is really cool, at first i was just like okay an eye...but looking better at it yes i like it it works. I just wish there was not so much light/glare next to it. but still a 7', '2003-09-12 16:48:15.000000', NULL, 1),
(417112, 37423, 11022, '<td valign="top">Really great image!</td>', 'Really great image!', '2003-09-12 16:51:01.000000', NULL, 1),
(417114, 37406, 11022, '<td valign="top">Free but not "fat free" ! *smile*  Nice clear shot</td>', 'Free but not "fat free" ! *smile*  Nice clear shot', '2003-09-12 16:51:37.000000', NULL, 1),
(417116, 37340, 11022, '<td valign="top">Very appropriate subject matter and beautifully executed.  The pen adds the perfect touch.</td>', 'Very appropriate subject matter and beautifully executed.  The pen adds the perfect touch.', '2003-09-12 16:52:27.000000', NULL, 1),
(417119, 37358, 342, '<td valign="top">it is nice to see other people who are proud of their flag.</td>', 'it is nice to see other people who are proud of their flag.', '2003-09-12 16:54:04.000000', NULL, 1),
(417120, 37423, 342, '<td valign="top">this would make a great looking album cover</td>', 'this would make a great looking album cover', '2003-09-12 16:54:32.000000', NULL, 1),
(417121, 37432, 6504, '<td valign="top">I love dogs -  maybe I''m biased.  But I think this is HILARIOUS!    I want you to be the winner.   It''s a good clear shot and the color is good.  It''s simple and look at him (her) go!!</td>', 'I love dogs -  maybe I''m biased.  But I think this is HILARIOUS!    I want you to be the winner.   It''s a good clear shot and the color is good.  It''s simple and look at him (her) go!!', '2003-09-12 16:57:35.000000', NULL, 1),
(417123, 37348, 10978, '<td valign="top">I hear ya!!!!</td>', 'I hear ya!!!!', '2003-09-12 16:59:17.000000', NULL, 1),
(417127, 37411, 11022, '<td valign="top">Wonderful interpretation.  It just reached out and grabbed me!</td>', 'Wonderful interpretation.  It just reached out and grabbed me!', '2003-09-12 17:05:38.000000', NULL, 1),
(417133, 37372, 8306, '<td valign="top">nice photo! what a way to show our freedom!  God Bless USA!</td>', 'nice photo! what a way to show our freedom!  God Bless USA!', '2003-09-12 17:24:58.000000', NULL, 1),
(417134, 37411, 1379, '<td valign="top">Yes, yes, yes!</td>', 'Yes, yes, yes!', '2003-09-12 17:27:15.000000', NULL, 1),
(417142, 37454, 4494, '<td valign="top">A printing press, great idea!  Nice effect "fading" it using your contrast.</td>', 'A printing press, great idea!  Nice effect "fading" it using your contrast.', '2003-09-12 17:36:02.000000', NULL, 1),
(417146, 37414, 2883, '<td valign="top">I love the clarity and blue color. It might be better with the top cropped just a bit.</td>', 'I love the clarity and blue color. It might be better with the top cropped just a bit.', '2003-09-12 17:37:20.000000', NULL, 1),
(417149, 37435, 2883, '<td valign="top">Nice statement and good focus.</td>', 'Nice statement and good focus.', '2003-09-12 17:38:29.000000', NULL, 1),
(417151, 37380, 2883, '<td valign="top">This is more patriotism than freedom. I think less cropping on top would have been better. Iike the saturation of the flag.</td>', 'This is more patriotism than freedom. I think less cropping on top would have been better. Iike the saturation of the flag.', '2003-09-12 17:39:36.000000', NULL, 1),
(417155, 37406, 2883, '<td valign="top">This photo has a good statement to it. The slight ghost images along the bottom edges of the flags, probably due to sharpening, are a little distracting.</td>', 'This photo has a good statement to it. The slight ghost images along the bottom edges of the flags, probably due to sharpening, are a little distracting.', '2003-09-12 17:41:07.000000', NULL, 1),
(417156, 37450, 2883, '<td valign="top">I think a camera angle closer to the words with the DOF showing the flag in focus would be a little more clear.</td>', 'I think a camera angle closer to the words with the DOF showing the flag in focus would be a little more clear.', '2003-09-12 17:41:47.000000', NULL, 1),
(417158, 37441, 2883, '<td valign="top">This is more of a patriotic photo, but very well done. I like the softness around the eye.</td>', 'This is more of a patriotic photo, but very well done. I like the softness around the eye.', '2003-09-12 17:42:35.000000', NULL, 1),
